1→#!/bin/bash
# MiniCPM5 2.6b short RL example, colocate.

:<<"EOF"
infra tuning ledger (MiniCPM5-2.6B @ 8k short, H100)
KV/token = 2(K,V) x 2 x 128 x 42 x 2B = 42 KiB   (1 GiB ~= 25k token)
changes (base -> tuned):
  rollout_batch_size        64 -> 256      (32/card x 8 cards)
  max_running_requests     128 -> 256
10→  max_total_tokens      131072 -> 1536000  (mem0.85, ~192 full-8k seqs/card)
  mem_fraction            0.75 -> 0.85
EOF

set -x
unset http_proxy HTTP_PROXY https_proxy HTTPS_PROXY no_proxy NO_PROXY

export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export CLUSTER=${CLUSTER:-ningxia_h100}

20→source scripts/setup/env.sh
bash scripts/setup/setup.sh
export SLIME_SCRIPT_NUM_GPUS=$GPUS_PER_NODE

BASE_DIR=${BASE_DIR:-/data/run/$PROJECT_NAME/$JOB_ID}
mkdir -p "$BASE_DIR"

export SGLANG_PATH=${WORK_DIR}/sglang
export ARG_MODE=true_on_policy
export WANDB_API_KEY=${WANDB_API_KEY:-i_dont_have_wandb_key}
30→USE_WANDB=${USE_WANDB:-0}

if [ "${SKIP_KILL:-0}" != "1" ]; then
  pkill -9 sglang || true
  sleep 3
  ray stop --force || true
  pkill -9 ray || true
  pkill -f "python3 train.py" || true
  sleep 3
  pkill -9 ray || true
40→  pkill -f "python3 train.py" || true
  pkill -9 redis || true
else
  echo "SKIP_KILL=1: skip pkill/ray stop cleanup"
fi

set -ex
export PYTHONBUFFERED=16

NVLINK_COUNT=$(nvidia-smi topo -m 2>/dev/null | grep -o 'NV[0-9][0-9]*' | wc -l || echo 0)
50→HAS_NVLINK=$([[ "$NVLINK_COUNT" -gt 0 ]] && echo 1 || echo 0)
echo "HAS_NVLINK: $HAS_NVLINK (detected $NVLINK_COUNT NVLink references)"

HF_MODEL_DIR=${HF_MODEL_DIR:-/models/MiniCPM5-2.6B}
HF_MODULES_DIR=${HF_MODULES_DIR:-/root/.cache/huggingface/modules}
HF_DYNAMIC_MODULE_NAME="$(basename "${HF_MODEL_DIR}" | sed 's/\./_dot_/g; s/-/_/g')"
HF_DYNAMIC_MODULE_DIR="${HF_MODULES_DIR}/transformers_modules/${HF_DYNAMIC_MODULE_NAME}"
mkdir -p "${HF_DYNAMIC_MODULE_DIR}"
touch "${HF_MODULES_DIR}/transformers_modules/__init__.py" "${HF_DYNAMIC_MODULE_DIR}/__init__.py"
for py_file in configuration_minicpm.py modeling_minicpm.py; do
60→  if [ -f "${HF_MODEL_DIR}/${py_file}" ]; then
    cp "${HF_MODEL_DIR}/${py_file}" "${HF_DYNAMIC_MODULE_DIR}/"
  fi
done

export MODEL_PATH=${HF_MODEL_DIR}
export MEGATRON_MODEL_PATH=${MEGATRON_MODEL_PATH:-/models/MiniCPM5-2.6B-torch_dist}
export CKPT_PATH=${CKPT_PATH:-${BASE_DIR}/checkpoints}
export PYTHONPATH=.:Megatron-LM/:mbridge:${SGLANG_PATH}/python:${HF_MODULES_DIR}:${WORK_DIR}/examples/retool_v2
source "${WORK_DIR}/scripts/minicpm5/2_6b/minicpm5-26b.sh"
70→
MODEL_ARGS_SELECTED=("${MODEL_ARGS[@]}")
MODEL_TAG=minicpm5_26b
TENSOR_MODEL_PARALLEL_SIZE=${TENSOR_MODEL_PARALLEL_SIZE:-1}
CONTEXT_PARALLEL_SIZE=${CONTEXT_PARALLEL_SIZE:-4}
ROLLOUT_NUM_GPUS_PER_ENGINE=${ROLLOUT_NUM_GPUS_PER_ENGINE:-1}
EXPERT_MODEL_PARALLEL_SIZE=${EXPERT_MODEL_PARALLEL_SIZE:-1}
OPTIMIZER=${OPTIMIZER:-adam}
SGLANG_EXTRA_ARGS=()

80→
TASK_TAG=short_math_8k
# TRAIN_FILE=${TRAIN_FILE:-/data/rl_math_s10_mathverify_dpsk_filtered.jsonl}
TRAIN_FILE=${TRAIN_FILE:-/datasets/simple-math.jsonl}
TEST_FILE=${TEST_FILE:-"aime2025 /datasets/aime-2025.jsonl aime2024 /datasets/aime-2024.jsonl"}
NUM_ROLLOUT=${NUM_ROLLOUT:-200}
ROLLOUT_BATCH_SIZE=${ROLLOUT_BATCH_SIZE:-256}
N_SAMPLES_PER_PROMPT=${N_SAMPLES_PER_PROMPT:-8}
ROLLOUT_MAX_PROMPT_LEN=${ROLLOUT_MAX_PROMPT_LEN:-2048}
ROLLOUT_MAX_RESPONSE_LEN=${ROLLOUT_MAX_RESPONSE_LEN:-6144}
90→ROLLOUT_MAX_CONTEXT_LEN=${ROLLOUT_MAX_CONTEXT_LEN:-8192}
SGLANG_CONTEXT_LEN=${SGLANG_CONTEXT_LEN:-8192}
MAX_TOKENS_PER_GPU=${MAX_TOKENS_PER_GPU:-8192}
LOGPROBS_MAX_TOKENS_PER_GPU=${LOGPROBS_MAX_TOKENS_PER_GPU:-${MAX_TOKENS_PER_GPU}}
SGLANG_MAX_TOTAL_TOKENS=${SGLANG_MAX_TOTAL_TOKENS:-1536000}
SGLANG_MAX_RUNNING_REQUESTS=${SGLANG_MAX_RUNNING_REQUESTS:-256}


export TENSORBOARD_DIR=${TENSORBOARD_DIR:-${BASE_DIR}/exp_log/tensorboard/${MODEL_TAG}_${TASK_TAG}}

100→GLOBAL_BATCH_SIZE=$((ROLLOUT_BATCH_SIZE * N_SAMPLES_PER_PROMPT))
LOG_PROBS_CHUNK_SIZE=${LOG_PROBS_CHUNK_SIZE:-2048}
SGLANG_MEM_FRACTION=${SGLANG_MEM_FRACTION:-0.85}
SGLANG_MAX_PREFILL_TOKENS=${SGLANG_MAX_PREFILL_TOKENS:-${SGLANG_CONTEXT_LEN}}
SGLANG_SCHEDULE_CONSERVATIVENESS=${SGLANG_SCHEDULE_CONSERVATIVENESS:-1.2}
EVAL_MAX_RESPONSE_LEN=${EVAL_MAX_RESPONSE_LEN:-${ROLLOUT_MAX_RESPONSE_LEN}}
RUN_TAG="$(date +%Y%m%d_%H%M%S)"
EXP_NAME="${MODEL_TAG}_${TASK_TAG}_${RUN_TAG}"

CKPT_ARGS=(
110→  --hf-checkpoint $MODEL_PATH
  --load $MEGATRON_MODEL_PATH
  --save ${CKPT_PATH}/${EXP_NAME}/
  --save-interval ${SAVE_INTERVAL:-50}
)

ROLLOUT_ARGS=(
  --prompt-data $TRAIN_FILE
  --input-key ${INPUT_KEY:-prompt}
  --label-key ${LABEL_KEY:-label}
120→  --apply-chat-template
  --apply-chat-template-kwargs '{"enable_thinking": false}'
  --rollout-shuffle
  --num-rollout ${NUM_ROLLOUT}
  --rollout-batch-size ${ROLLOUT_BATCH_SIZE}
  --n-samples-per-prompt ${N_SAMPLES_PER_PROMPT}
  --rollout-max-prompt-len ${ROLLOUT_MAX_PROMPT_LEN}
  --rollout-max-response-len ${ROLLOUT_MAX_RESPONSE_LEN}
  --rollout-max-context-len ${ROLLOUT_MAX_CONTEXT_LEN}
  --rollout-temperature ${ROLLOUT_TEMPERATURE:-1.0}
130→  --rollout-top-p ${ROLLOUT_TOP_P:-1.0}
  --global-batch-size ${GLOBAL_BATCH_SIZE}
  --balance-data
)

ROLLOUT_ARGS+=(
  --rm-type math
  --dynamic-sampling-filter-path miles.rollout.filter_hub.dynamic_sampling_filters.check_reward_nonzero_std
)
CUSTOM_ARGS=()
140→
PERF_ARGS=(
  --train-backend megatron
  --tensor-model-parallel-size ${TENSOR_MODEL_PARALLEL_SIZE}
  --context-parallel-size ${CONTEXT_PARALLEL_SIZE}
  --sequence-parallel
  --pipeline-model-parallel-size 1
  --expert-model-parallel-size ${EXPERT_MODEL_PARALLEL_SIZE}
  --expert-tensor-parallel-size 1
  --attention-backend ${ATTENTION_BACKEND:-flash}
150→  --recompute-granularity full
  --recompute-method uniform
  --recompute-num-layers 1
  --use-dynamic-batch-size
  --max-tokens-per-gpu ${MAX_TOKENS_PER_GPU}
  --log-probs-max-tokens-per-gpu ${LOGPROBS_MAX_TOKENS_PER_GPU}
  --log-probs-chunk-size ${LOG_PROBS_CHUNK_SIZE}
)

GRPO_ARGS=(
160→  --advantage-estimator grpo
  --disable-grpo-std-normalization
  --kl-loss-coef 0.00
  --kl-loss-type low_var_kl
  --entropy-coef 0.00
  --calculate-per-token-loss
  --eps-clip 0.2
  --eps-clip-high 0.28
)

170→GRPO_ARGS+=(
  --use-tis
  --custom-tis-function-path miles.backends.training_utils.loss.icepop_function
  --tis-clip-low 0.5
  --tis-clip 5.0
)


if [ "$OPTIMIZER" = "muon" ]; then
  OPTIMIZER_ARGS=(
180→    --optimizer muon
    --lr ${LR:-1e-6}
    --lr-decay-style constant
    --weight-decay 0.1
    --adam-beta1 0.9
    --adam-beta2 0.98
    --muon-matched-adamw-rms 0.2
    --muon-momentum 0.95
    --muon-ns-steps 5
    --muon-coefficient-type simple
190→  )
else
  OPTIMIZER_ARGS=(
    --optimizer adam
    --lr ${LR:-1e-6}
    --lr-decay-style constant
    --weight-decay 0.1
    --adam-beta1 0.9
    --adam-beta2 0.98
  )
200→fi

WANDB_ARGS=(--use-tensorboard)
if [ "${USE_WANDB}" = "1" ]; then
  WANDB_ARGS+=(--use-wandb --wandb-project ${WANDB_PROJECT:-miles-minicpm5})
  if [ -n "${WANDB_TEAM:-}" ]; then
    WANDB_ARGS+=(--wandb-team "${WANDB_TEAM}")
  fi
fi

210→SGLANG_ARGS=(
  --rollout-num-gpus-per-engine ${ROLLOUT_NUM_GPUS_PER_ENGINE}
  --sglang-mem-fraction-static ${SGLANG_MEM_FRACTION}
  --sglang-max-running-requests ${SGLANG_MAX_RUNNING_REQUESTS}
  --sglang-schedule-conservativeness ${SGLANG_SCHEDULE_CONSERVATIVENESS}
  --sglang-attention-backend fa3
  --sglang-json-model-override-args "{\"max_position_embeddings\": ${SGLANG_CONTEXT_LEN}}"
  --sglang-context-length ${SGLANG_CONTEXT_LEN}
  --sglang-max-prefill-tokens ${SGLANG_MAX_PREFILL_TOKENS}
  --sglang-max-total-tokens ${SGLANG_MAX_TOTAL_TOKENS}
220→  "${SGLANG_EXTRA_ARGS[@]}"
)

EVAL_ARGS=(
  --eval-prompt-data $TEST_FILE
  --eval-interval ${EVAL_INTERVAL:-5}
  --eval-temperature ${EVAL_TEMPERATURE:-0.6}
  --eval-max-response-len ${EVAL_MAX_RESPONSE_LEN}
  --n-samples-per-eval-prompt ${N_SAMPLES_PER_EVAL_PROMPT:-1}
)
230→
mkdir -p ${CKPT_PATH}/${EXP_NAME}/dump_details
MISC_ARGS=(
  --attention-dropout 0.0
  --hidden-dropout 0.0
)

RUNTIME_ENV_JSON="{
  \"env_vars\": {
    \"PYTHONPATH\":  \".:./Megatron-LM:./mbridge:${SGLANG_PATH}/python:${WORK_DIR}/examples/retool_v2:/root/.cache/huggingface/modules\",
240→    \"CUDA_DEVICE_MAX_CONNECTIONS\": \"1\",
    \"NCCL_NVLS_ENABLE\": \"${HAS_NVLINK}\",
    \"SGLANG_ALLOW_OVERWRITE_LONGER_CONTEXT_LEN\": \"1\",
    \"NVTE_DEBUG\": \"${NVTE_DEBUG:-0}\",
    \"NVTE_DEBUG_LEVEL\": \"${NVTE_DEBUG_LEVEL:-0}\",
    \"NVTE_FUSED_ATTN\": \"0\",
    \"NVTE_UNFUSED_ATTN\": \"0\",
    \"SGLANG_CLIP_MAX_NEW_TOKENS_ESTIMATION\": \"10000\",
    \"TRITON_CACHE_DIR\": \"${TRITON_CACHE_DIR}\",
    \"TMPDIR\": \"${TMPDIR}\",
250→    \"MILES_EXPERIMENTAL_ROLLOUT_REFACTOR\": \"1\"
  }
}"

bash scripts/setup/ray_start.sh

echo "============================================================"
echo "${MODEL_TAG} ${TASK_TAG}: colocate RL"
echo "rollouts=${NUM_ROLLOUT}, batch=${ROLLOUT_BATCH_SIZE}, samples=${N_SAMPLES_PER_PROMPT}"
echo "TP=${TENSOR_MODEL_PARALLEL_SIZE}, CP=${CONTEXT_PARALLEL_SIZE}, EP=${EXPERT_MODEL_PARALLEL_SIZE}, sglang_tp=${ROLLOUT_NUM_GPUS_PER_ENGINE}"
260→echo "prompt_len=${ROLLOUT_MAX_PROMPT_LEN}, response_len=${ROLLOUT_MAX_RESPONSE_LEN}, context_len=${ROLLOUT_MAX_CONTEXT_LEN}"
echo "partial_rollout=0"
echo "EXP=${EXP_NAME}"
echo "BASE_DIR=${BASE_DIR}"
echo "============================================================"

ray job submit --address="http://${MASTER_ADDR}:8265" \
  --runtime-env-json="${RUNTIME_ENV_JSON}" \
  -- python3 train.py \
  --actor-num-nodes ${WORLD_SIZE} \
270→  --actor-num-gpus-per-node ${GPUS_PER_NODE} \
  --colocate \
  --start-rollout-id 0 \
  --skip-eval-before-train \
  "${MODEL_ARGS_SELECTED[@]}" \
  "${CKPT_ARGS[@]}" \
  "${ROLLOUT_ARGS[@]}" \
  "${OPTIMIZER_ARGS[@]}" \
  "${GRPO_ARGS[@]}" \
  "${WANDB_ARGS[@]}" \
280→  "${PERF_ARGS[@]}" \
  "${SGLANG_ARGS[@]}" \
  "${EVAL_ARGS[@]}" \
  "${CUSTOM_ARGS[@]}" \
  "${MISC_ARGS[@]}" "$@"

bash $WORK_DIR/scripts/setup/ray_end.sh
echo "${MODEL_TAG} ${TASK_TAG} done! EXP=${EXP_NAME}"

